uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings (Original preserved)
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;
uniform float u_density;
uniform float u_connection_radius;
uniform float u_pulse_intensity;
uniform float u_color_base;
uniform float u_color_pulse;

// New Parameter for organic motion
uniform float u_wind_strength;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// 1D Hash
float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// 2D Hash
vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

// Distance to a line segment
float distLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

// Smooth HSV to RGB
vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Organic Branching logic
void addBranch(vec2 f, vec2 p1, vec2 offs, vec2 dir, vec2 id, float t, float coreSharpness, float haloSharpness, float fade, vec3 baseCol, vec3 pulseCol, float connRadius, float pulseInt, inout vec3 layerColor) {
    vec2 offs2 = offs + dir;

    // Position of the neighbor node, with "sway" for wind
    vec2 p2 = offs2 + 0.5 + 0.4 * sin(t * 1.5 + hash22(id + offs2) * 6.28 + u_wind_strength);
    float dConn = distance(p1, p2);

    // Trees branch upwards/outwards - filter connections slightly to look like growth
    float angle = atan(p2.y - p1.y, p2.x - p1.x);
    bool isVerticalGrowth = p2.y > p1.y - 0.2; // Tend towards upward growth

    if(dConn < connRadius && isVerticalGrowth) {
        float dLine = distLine(f, p1, p2);

        // Growth Flow Logic (Sap/Nutrient Flow)
        float flowTime = t * 4.0 - length(p1) * 2.0;
        float pulse = smoothstep(0.7, 1.0, sin(dConn * 3.0 - flowTime + hash21(id)*10.0));

        // Branch Thickness - thicker at "roots" (p1) thinner at "tips" (p2)
        float thickness = mix(1.0, 0.4, clamp(dConn / connRadius, 0.0, 1.0));
        float branchTotal = exp(-dLine * coreSharpness / thickness) + exp(-dLine * (haloSharpness * 0.5)) * 0.6;

        // Bloom/Leaf Logic
        float leaf = smoothstep(0.1, 0.0, dLine) * step(0.8, hash21(id + dir));

        float connFade = smoothstep(connRadius, connRadius * 0.3, dConn);

        // Color accumulation: Forest greens and blossom pinks
        vec3 branchCol = mix(baseCol, pulseCol, pulse * pulseInt);
        layerColor += branchCol * branchTotal * connFade * fade;

        // Add "Leaves" or "Blooms" at the end of branches
        float leafSpot = smoothstep(0.15, 0.0, distance(f, p2));
        layerColor += pulseCol * leafSpot * fade * pulseInt * 0.5;
    }
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // Parameters
    float spd = (u_speed <= 0.0) ? 0.1 : u_speed;
    float t = iTime * spd;
    float brightness = (u_intensity <= 0.0) ? 1.0 : u_intensity;
    float scaleBase = (u_scale <= 0.0) ? 1.0 : u_scale;
    float layerCount = floor((u_layers <= 0.0) ? 4.0 : u_layers);

    float density = (u_density <= 0.0) ? 1.0 : u_density; 
    float connRadius = (u_connection_radius <= 0.0) ? 1.2 : u_connection_radius;
    float pulseInt = (u_pulse_intensity <= 0.0) ? 1.0 : u_pulse_intensity;

    // Organic Color palette: Base = Forest Green, Pulse = Flower Pink/Yellow
    float hueBase = fract(u_color_base + (t * u_color_cycle * 0.05));
    float huePulse = fract(u_color_pulse + (t * u_color_cycle * 0.05));

    vec3 baseCol = hsv2rgb(vec3(hueBase, 0.7, 0.6)); // Deep mossy green
    vec3 pulseCol = hsv2rgb(vec3(huePulse, 0.6, 1.0)); // Bright blossom

    // Background: Deep forest floor gradient
    vec3 bgCenter = baseCol * 0.1;
    vec3 bgEdge = vec3(0.02, 0.04, 0.02);
    vec3 finalColor = mix(bgCenter, bgEdge, length(uv0));

    // Volumetric Forest Layering
    for(int i = 0; i < 8; i++) {
        float fi = float(i);
        if(fi >= layerCount) break;

        // Z-depth for infinite zoom through the canopy
        float z = fract(fi * (1.0/layerCount) + t * 0.05); 
        float fade = smoothstep(0.0, 0.3, z) * smoothstep(1.0, 0.7, z);
        float blur = smoothstep(0.0, 0.6, abs(z - 0.5)); 

        float coreSharpness = mix(80.0, 15.0, blur);
        float haloSharpness = mix(20.0, 5.0, blur);

        // Scale space for tree structures
        float size = mix(15.0, 2.0, z) * scaleBase * density;
        vec2 layerUV = uv * size;

        // Gentle swaying movement
        layerUV.x += sin(t + z * 10.0) * 0.1 * u_wind_strength;
        layerUV *= rot(sin(t * 0.2 + fi) * 0.1 * u_wind_strength);

        vec2 id = floor(layerUV);
        vec2 f = fract(layerUV);

        vec3 layerColor = vec3(0.0);
        float nodeMass = 0.0;

        for(int y = -1; y <= 1; y++) {
            for(int x = -1; x <= 1; x++) {
                vec2 offs = vec2(float(x), float(y));

                // Node position (the "joint" of branches)
                vec2 p1 = offs + 0.5 + 0.4 * sin(t * 1.5 + hash22(id + offs) * 6.28 + u_wind_strength);

                // Draw Node (The Bud)
                float dNode = length(f - p1);
                nodeMass += exp(-dNode * coreSharpness) + (exp(-dNode * haloSharpness) * 0.5);

                // Tree Branching Structure (Directed connections)
                addBranch(f, p1, offs, vec2(0.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius, pulseInt, layerColor); // Up
                addBranch(f, p1, offs, vec2(1.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius, pulseInt, layerColor); // Up-Right
                addBranch(f, p1, offs, vec2(-1.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius, pulseInt, layerColor); // Up-Left
                addBranch(f, p1, offs, vec2(1.0, 0.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius * 0.5, pulseInt, layerColor); // Side
            }
        }

        // Add organic highlights
        layerColor += mix(baseCol, vec3(0.8, 1.0, 0.6), 0.4) * nodeMass * fade;

        finalColor += layerColor * brightness;
    }

    // Post-Processing: Sun rays/Vignette
    float vig = 1.0 - length(uv0) * 0.6;
    finalColor *= vig;

    // Light Bloom / Tone mapping
    finalColor = smoothstep(-0.05, 1.1, finalColor * 1.2);
    finalColor = pow(finalColor, vec3(0.9));

    fragColor = vec4(finalColor, 1.0);
}
